```hcl
# Disable Always Online to prevent serving stale cached content
resource "cloudflare_zone_settings_override" "always_online" {
  zone_id = "<ZONE_ID>"
  settings {
    always_online = "off" # Critical: prevents serving potentially stale or sensitive cached content
  }
}
```

```hcl
# Enable Automatic HTTPS Rewrites to fix mixed content
resource "cloudflare_zone_settings_override" "https_rewrites" {
  zone_id = "<ZONE_ID>"
  settings {
    automatic_https_rewrites = "on" # Critical: automatically rewrites HTTP URLs to HTTPS
  }
}
```

