```hcl
# Enable HSTS with recommended settings
resource "cloudflare_zone_setting" "security_header" {
  zone_id    = "<ZONE_ID>"
  setting_id = "security_header"
  value = {
    strict_transport_security = {
      enabled            = true
      max_age            = 31536000  # Critical: 1 year in seconds
      include_subdomains = true      # Recommended: apply to all subdomains
      preload            = true      # Recommended: submit to browser preload lists
    }
  }
}
```

