```hcl
# Configure Rate Limiting to protect against volumetric attacks
resource "cloudflare_ruleset" "rate_limit" {
  zone_id = "<ZONE_ID>"
  name    = "Rate limiting"
  kind    = "zone"
  phase   = "http_ratelimit"
  rules {
    action = "block"
    ratelimit {
      characteristics     = ["ip.src"]
      period              = 60
      requests_per_period = 100
      mitigation_timeout  = 600
    }
    expression  = "true"
    description = "Rate limit all requests"
  }
}
```

```hcl
# Create CAA record to restrict certificate issuance
resource "cloudflare_record" "caa_issue" {
  zone_id = "<ZONE_ID>"
  name    = "@"
  type    = "CAA"
  data {
    flags = "0"
    tag   = "issue"                # Restricts which CAs can issue regular certificates
    value = "letsencrypt.org"      # Specify your authorized certificate authority
  }
}

# Create CAA record to restrict wildcard certificate issuance
resource "cloudflare_record" "caa_issuewild" {
  zone_id = "<ZONE_ID>"
  name    = "@"
  type    = "CAA"
  data {
    flags = "0"
    tag   = "issuewild"            # Restricts which CAs can issue wildcard certificates
    value = "letsencrypt.org"
  }
}
```

